const mockFlight = (weeksAgo: number): Flight => ({
  id: `f${weeksAgo}`,
  flight_code: `FLT-2026-W${35 - weeksAgo}-OAKWOOD`,
  flown_at: daysAgo(2 + weeksAgo * 7),
  neighborhood: "Oakwood",
  drone_model: "DJI Mavic 3 Classic",
  altitude_m: 90,
  gsd_cm_per_px: 2.4,
  notes: weeksAgo === 0 ? "Light haze; two parcels re-flown" : null,
  created_at: daysAgo(2 + weeksAgo * 7),
});

/** The four most recent weekly sorties, newest first. */
export const MOCK_FLIGHTS: Flight[] = [0, 1, 2, 3].map(mockFlight);

/** Per-parcel factor inputs behind the mock scans, mirroring the generated
 *  imagery: flagged parcels overgrow and stand out from the grid, m2 keeps a
 *  static sedan, m5 is an occupied home whose car comes and goes. */
function mockFactorInputs(propertyId: string, w: number) {
  const lead = MOCK_LEADS.find((l) => l.id === propertyId);
  const flagged = lead?.status !== "active";
  // How strongly each parcel's imagery reads as neglected (0..1); m4 is the
  // textbook case, m3 is borderline, m5 is a maintained, occupied home.
  const intensity = { m1: 0.75, m2: 0.6, m3: 0.45, m4: 0.95, m5: 0, m6: 0.55 }[propertyId] ?? 0.4;
  const lgi = Number(((lead?.latest_lawn_growth_index ?? 0.3) - w * 0.12).toFixed(2));
  const change = Number((3.1 + w * 0.8).toFixed(1));
  const vehiclePresent = propertyId === "m2" || (propertyId === "m5" && w % 2 === 0);
  const vehicleStatic = propertyId === "m2";
  const alignment = w === 2 ? 0.41 : 0.87;
  const fade = Math.max(0, 1 - w * 0.25); // older sorties looked less conclusive
  return {
    lgi,
    change,
    vehiclePresent,
    vehicleStatic,
    alignment,
    factors: {
      lawn_growth: lgi,
      greenness_level: flagged ? 0.12 + 0.12 * intensity * fade : 0.1,
      texture_level: flagged ? 300 + 320 * intensity * fade : 260,
      greenness_vs_grid: flagged ? 1.5 * intensity * fade : -0.8,
      texture_vs_grid: flagged ? 1.2 * intensity * fade : -0.5,
      vehicle_static: vehicleStatic ? 1 : 0,
      vehicle_absent: vehiclePresent ? 0 : 1,
      stillness: Math.max(0, 1 - change / 12),
      clutter: 0.6 + 2 * intensity,
      persistence_weeks: flagged ? Math.max(0, Math.round(3 * intensity) - w) : 0,
      lgi_trend: flagged ? 0.08 * intensity : -0.02,
      alignment_quality: alignment,
    },
  };
}

export function mockScansFor(propertyId: string): PropertyScan[] {
  return [0, 1, 2, 3].map((w) => {
    const input = mockFactorInputs(propertyId, w);
    const score = scoreFactors(input.factors);
    return {
      id: `${propertyId}-s${w}`,
      property_id: propertyId,
      flight_id: `f${w}`,
      image_url_current: img(propertyId, 35 - w),
      image_url_previous: img(propertyId, 34 - w),
      image_url_diff: diffImg(propertyId, 35 - w),
      lawn_growth_index: input.lgi,
      vehicle_present: input.vehiclePresent,
      vehicle_static: input.vehicleStatic,
      change_score: input.change,
      vacancy_confidence: score.confidence,
      alignment_quality: input.alignment,
      processed_at: daysAgo(2 + w * 7),
      raw_metrics: { details: { low_alignment: input.alignment < 0.5 } },
      factor_scores: score,
      model_version: score.model_version,
      flight: mockFlight(w),
    };
  });
}

// Keep the grid's headline number identical to what the model says about the
// latest sortie, so the command center and the verification workspace agree.
for (const lead of MOCK_LEADS) {
  lead.latest_vacancy_confidence = mockScansFor(lead.id)[0].vacancy_confidence;
}

/** Verification history seeded for the mock leads that carry a verdict. */
export function mockVerificationsFor(propertyId: string): PropertyVerification[] {
  const lead = MOCK_LEADS.find((l) => l.id === propertyId);
  if (!lead?.verification) return [];
  return [
    {
      id: `${propertyId}-v1`,
      property_id: propertyId,
      scan_id: `${propertyId}-s0`,
      verdict: lead.verification,
      note:
        lead.verification === "needs_recheck"
          ? "Shadow across the drive; re-fly before deciding."
          : "Confirmed against W35 imagery.",
      verified_by: "operator",
      created_at: lead.verified_at ?? daysAgo(3),
    },
  ];
}

