/** Timeline seeded for the mock leads, newest first. */
export function mockActivitiesFor(propertyId: string): Activity[] {
  const row = (
    id: string,
    kind: Activity["kind"],
    body: string,
    createdDaysAgo: number,
    extra: Partial<Activity> = {},
  ): Activity => ({
    id: `${propertyId}-${id}`,
    property_id: propertyId,
    contact_id: null,
    kind,
    body,
    outcome: null,
    amount: null,
    due_at: null,
    completed_at: null,
    created_by: "operator",
    created_at: daysAgo(createdDaysAgo),
    ...extra,
  });
  if (propertyId === "m1") {
    return [
      row("a3", "task", "Pull the tax lien payoff amount from the county portal", 1, {
        due_at: daysAgo(-2),
      }),
      row("a2", "call", "Spoke with Denise — open to selling, wants to clear the lien first.", 3, {
        contact_id: "m1-c1",
        outcome: "interested",
      }),
      row("a1", "stage_change", "Verified → Researching", 4),
    ];
  }
  if (propertyId === "m4") {
    return [
      row("a4", "task", "Confirm the estate has letters testamentary on file", 2, {
        due_at: daysAgo(1),
      }),
      row("a3", "offer", "Initial cash offer, 21-day close, as-is.", 5, {
        contact_id: "m4-c1",
        amount: 165000,
        outcome: "countered",
      }),
      row("a2", "mailer", "Probate letter #2 mailed to the estate attorney.", 12),
      row("a1", "stage_change", "Outreach → Negotiating", 6),
    ];
  }
  if (propertyId === "m2") {
    return [
      row("a1", "task", "Drive by — confirm the sedan has not moved", 1, { due_at: daysAgo(0) }),
    ];
  }
  return [];
}
